UPDATE catalog_categories
SET name = CAST(#{name} AS jsonb), active = #{active}, updated_at = #{now}, updated_by = #{staffId}
WHERE id = #{id}

UPDATE catalog_items
SET image = #{png,jdbcType=BINARY}, image_thumb = #{thumb,jdbcType=BINARY}, image_version = image_version + 1,
    updated_at = #{now}, updated_by = #{staffId}
WHERE id = #{id}
